from pathlib import Path
import csv,json,statistics
ROOT=Path('D:/SEM_5/ML_PROJECT')
OUT=ROOT/'tmp/presentation_build'
rows=list(csv.DictReader((ROOT/'statistical result/average_metric_scores.csv').open()))
rows=[r for r in rows if r['population']=='strict_all_methods' and r['classifier'] in ['svm','knn','rf','lr']]
methods=['ros','smote','bsmote','adasyn','casb','casb_relaxed','casb_edited','casb_ros']
names={'ros':'ROS','smote':'SMOTE','bsmote':'Borderline-SMOTE','adasyn':'ADASYN','casb':'CASB','casb_relaxed':'CASB-relaxed','casb_edited':'CASB-edited','casb_ros':'CASB-ROS'}
metrics=['gmean','f1','precision','recall']
avg=[]
for m in methods:
 rr=[r for r in rows if r['method']==m];assert len(rr)==4
 avg.append([names[m]]+[f'{100*statistics.mean(float(r[v]) for r in rr):.3f}' for v in metrics])
slides=[]
def add(kind,title,section,notes,source='latex_paper/manuscript.tex',**kw):
 slides.append(dict(kind=kind,title=title,section=section,notes=notes,source=source,**kw))
def plot(title,section,file,take,notes):
 add('plot',title,section,notes,source=file,image=str(ROOT/file),take=take)
add('cover','CASB family','Research presentation',
 'Good morning. We study how to distribute synthetic minority samples across different regions of an imbalanced dataset. I will explain the problem, earlier methods, our experimental setup, the four CASB variants and the evidence. The main result is a classifier-dependent tradeoff, rather than a claim that one method wins everywhere.',
 subtitle='Coverage-aware oversampling for binary classification',authors='Pulkit Sharma   •   Priyanshu Kumar   •   Niranjan Yadav',affiliation='Department of Artificial Intelligence\nSVNIT, Surat')
add('problem','High accuracy can hide missed minority cases','01  Problem and objectives',
 'Consider a dataset containing 95 majority observations and 5 minority observations. A classifier that always predicts the majority class has 95 percent accuracy but zero minority recall. This is an illustrative example, not a benchmark result. Our concern is whether a resampling method improves the detection of minority cases without creating too many false positives.',
 values=['95%','0%'],labels=['Accuracy','Minority recall'],take='Illustrative 95:5 dataset: always predicting the majority misses every minority case.')
add('bullets','Research objectives','01  Problem and objectives',
 'Our first objective is to retain broad source eligibility while giving some generation budget to boundary and sparse minority regions. We then separate the effect of interpolation, relaxing its distance limit, cleaning majority observations and duplicating sources. We evaluate the variants using several classifiers and report each metric separately. These are research objectives, not promises of universal improvement.',
 bullets=['Share the generation budget across minority regions','Compare capped interpolation, full interpolation and copying','Measure recall gains alongside precision costs','Test performance across datasets and classifiers'],take='Research question: where should synthetic generation begin?')
add('table','Established resampling methods','02  Literature review',
 'ROS repeats existing minority observations. SMOTE generates points along minority-neighbour segments. Borderline-SMOTE concentrates on locally mixed minority observations. ADASYN allocates more points to locally difficult cases. These mechanisms address different needs, but local class composition cannot prove that a source label or an interpolation path is reliable. We use borderline-1 in the benchmark.',
 source='references.bib: chawla2002, han2005, he2008',headers=['Method','Main action','Relevant limitation'],rows=[['ROS','Repeat minority samples','Can repeat unreliable labels'],['SMOTE','Interpolate between neighbours','May cross majority regions'],['Borderline-SMOTE','Focus on danger sources','Other sources receive no direct quota'],['ADASYN','Weight locally difficult sources','Difficulty can also reflect noise']],widths=[.21,.36,.43],take='Local difficulty and reliable labels are different questions.')
add('table','Closest ideas in previous work','02  Literature review',
 'Minority instance types and type-specific selection are close predecessors. Safe-Level-SMOTE and Geometric SMOTE adapt the geometry of generation. LNE learns resampling intensity from neighbourhood types. UGO uses classifier uncertainty with iterative processing. CASB studies a fixed mixture of overlapping pools with four generation or cleaning configurations. We do not claim that identifying minority types is new, and these close methods were not benchmarked here.',
 source='references.bib: safe2009, geometric2019, napierala2016, skryjomski2017, lne2024, saglam2026',
 headers=['Prior approach','Connection to CASB'],rows=[['Minority instance types','Safe, borderline, rare and outlier structure'],['Safe-Level / Geometric SMOTE','Local information guides synthetic generation'],['LNE','Neighbourhood types control resampling intensity'],['UGO','Shared framework with different generators']],widths=[.38,.62],take='CASB studies a particular combination of source allocation and generation rules.')
add('numbers','Benchmark scope','03  Data and evaluation',
 'The collection contains 44 binary KEEL tasks. We use the supplied five train/test folds and two random seeds. Four tasks have incomplete ADASYN evaluations, so the strict comparison with all current methods uses 40 datasets for every method. Across the four classifiers there are 15,840 attempted current evaluations, including 52 ADASYN failures. The two Abalone tasks use training-fitted one-hot encoding for the Sex feature.',
 values=['44','40','4'],labels=['Binary KEEL tasks','Complete matched tasks','Classifiers'],bullets=['Five supplied folds and two seeds','Abalone categorical feature: training-fitted one-hot encoding','52 failed ADASYN evaluations remain explicit'],take='Examples: Ecoli, Glass, Yeast, Abalone, Pima and Haberman')
add('flow','Training and evaluation protocol','03  Data and evaluation',
 'The outer test set remains untouched while the resampling ratio is selected. Inside each outer training fold, a stratified 25 percent validation split compares ratios 0.5, 0.75 and 1.0. The selection objective is the average of G-mean and F1, with ties favouring the lower ratio. Preprocessing is fitted only on training data. We then refit on the full outer training fold and evaluate on the held-out test set. Fold and seed results are averaged within each dataset.',
 steps=['Outer training fold','Inner ratio selection','Refit and resample','Held-out test'],details=['Fit preprocessing','Ratios 0.50 / 0.75 / 1.00','Use selected ratio','No tuning on test data'],take='Two seeds reuse the same folds; they are not independent datasets.')
add('table','Four classifier families','03 Data and evaluation',
 'We test four different learning mechanisms. SVM uses an RBF kernel with C equal to one. KNN uses seven neighbours and distance weighting. Random forest uses one hundred trees with minimum leaf size two. Logistic regression uses a maximum of three thousand iterations. This is not an exhaustive classifier hyperparameter search. RF and LR were retained after seeing development results, so the study remains exploratory.',
 headers=['Classifier','Configuration','What it learns'],rows=[['SVM','RBF kernel, C = 1','A nonlinear margin'],['KNN','7 neighbours, distance weights','Local class structure'],['Random forest','100 trees, minimum leaf size 2','Tree splits and class proportions'],['Logistic regression','Maximum 3,000 iterations','A linear decision score']],widths=[.25,.4,.35],take='Same outer partitions and training-only ratio selection')
add('table','Four metrics describe different costs','03 Data and evaluation',
 'G-mean combines minority and majority recall, so it penalizes a model that succeeds on only one class. F1 balances minority precision and recall. Precision asks how many positive predictions are correct. Recall asks how many true minority cases are detected. We report them separately because a resampling method can improve recall while reducing precision.',
 headers=['Metric','Interpretation'],rows=[['G-mean','Balance detection across both classes'],['F1','Balance minority precision and recall'],['Precision','How many predicted minority cases are correct?'],['Recall','How many true minority cases are detected?']],widths=[.25,.75],take='No composite score hides a precision–recall tradeoff.')
plot('CASB workflow','04  Proposed method','paper_material/02_casb_family_workflow.png','Allocation depends on neighbourhood geometry, not classifier uncertainty.',
 'Read the workflow from left to right. First preprocess the original training data. Then calculate minority neighbourhood information and form overlapping source pools. Allocate an integer generation budget and select a variant. The original and relaxed variants interpolate, CASB-ROS duplicates selected sources, and the edited variant performs majority-only ENN after relaxed generation. Finally train the classifier. No test-set information enters these steps.')
add('flow','CASB: choose where to start and how far to move','04  Proposed method',
 'CASB means Coverage-Aware Safe-Border SMOTE. The method uses only the training set. Its first decision is where to start: sources come from a mixture of all minority observations, locally mixed observations and sparse minority observations. Its second decision is how far to move from a selected source toward a minority neighbour. Unlike plain SMOTE, the original CASB restricts that movement for selected branches using the nearest observed majority distance. The word safe describes the design intention, not a guarantee of a correct synthetic label.',
 steps=['Measure local structure','Build source pools','Allocate additions','Generate new points'],details=['Labels and distances','Coverage / border / rare','50% / 30% / 20%','Select source, neighbour and step'],take='Two decisions: which minority point to use, and how far to interpolate.')
add('table','Step 1: identify useful minority sources','04  Proposed method',
 'For each minority observation, inspect up to ten nearest training observations, excluding its own index. Record the majority fraction and minority support. Also measure the distance to the nearest majority observation and to the third nearest minority neighbour, or the last available neighbour if fewer exist. Coverage contains every minority observation. Border sources have a majority fraction above 20 percent and at most 70 percent, with at least two minority neighbours and positive majority distance. Rare sources have a sparsity distance at or above the 75th percentile, with the same support and distance checks. These pools overlap; rare does not mean that a genuine rare class cluster has been verified.',
 headers=['Pool','Selection rule','Purpose'],rows=[['Coverage (C)','Every minority observation','Keep broad source eligibility'],['Border (B)','20% < majority fraction <= 70%','Focus on locally mixed regions'],['Rare (R)','Minority distance in top quartile','Include sparse minority regions']],widths=[.22,.44,.34],take='Border and rare also require at least 2 minority neighbours and positive majority distance.')
plot('Three overlapping source pools','04  Proposed method','paper_material/04_source_pools.png','Coverage includes every minority observation. Border and rare pools may overlap.',
 'Coverage is the complete minority set. Border eligibility uses a local majority fraction greater than 0.2 and at most 0.7, at least two minority neighbours and positive nearest-majority distance. Rare eligibility uses the upper quartile of third-minority-neighbour distance, with the same support and positive-distance checks. Rare is a geometric proxy, not a confirmed rare population. The figure uses constructed two-dimensional data.')
add('numbers','Step 2: divide the generation budget','04  Proposed method',
 'First choose the target minority-to-majority ratio using training-only validation. The number of additions is the ceiling of target ratio times majority count, minus the current minority count, with a minimum of zero. For example, 100 majority and 20 minority observations at ratio 0.75 need 55 additions. Original CASB divides these into 28 coverage, 16 border and 11 rare additions using largest-remainder rounding. Within each branch, sources are sampled uniformly with replacement. A source can be chosen repeatedly. An empty border or rare pool falls back to coverage for source selection, while retaining the allocated branch generation rule. Coverage eligibility does not guarantee that every minority point is actually selected.',
 values=['28','16','11'],labels=['Coverage additions','Border additions','Rare additions'],bullets=['Example: 100 majority + 20 minority; target ratio = 0.75','Need 55 additions; original quotas = 50 / 30 / 20','Choose sources uniformly within each pool, with replacement'],take='The quotas divide new samples, not the original minority observations.')
add('table','Step 3: limit movement using majority distance','04  Proposed method',
 'After selecting a source, choose one of its up to five nearest minority neighbours; the rare branch uses only the nearest two. Let L be the distance from source to selected neighbour and d the distance to the nearest majority observation. Generate z equals source plus lambda times neighbour minus source. Lambda is uniform from zero to the branch maximum. Coverage with at most 20 percent majority neighbours permits the full segment. The rare branch permits a movement of at most 0.35 times d; other capped steps permit at most 0.50 times d. Neither cap exceeds the selected segment length. A zero-length segment repeats the source. For example, L equals four and d equals two gives a maximum lambda of 0.25 for an ordinary capped step, and 0.175 for a rare step.',
 headers=['Allocated branch','Maximum movement from source'],rows=[['Coverage; majority fraction <= 20%','Full source-to-neighbour segment'],['Rare branch','Smaller of segment length and 0.35 x d'],['Other coverage / border steps','Smaller of segment length and 0.50 x d']],widths=[.49,.51],take='d = distance to the nearest observed majority point; a cap does not certify the label.')
plot('The interpolation rule','04  Proposed method','paper_material/03_interpolation_geometry.png','CASB retains SMOTE’s line-segment generator; some branches limit the step.',
 'The generated point is z equals the source plus lambda times the difference between its selected neighbour and source. The original method caps selected branches using nearest-majority distance. The relaxed method allows the full nonzero segment, and CASB-ROS uses a zero step to repeat the source. The distance cap is a geometric restriction, not a guarantee that the synthetic label is correct.')
add('table','The three extensions: what changes?','04  Proposed method',
 'CASB-relaxed keeps the same source-pool definitions but changes the quotas to 70, 20 and 10 percent and permits the full segment for every nonzero edge. It changes both allocation and the interpolation restriction. CASB-edited first runs relaxed generation, then applies three-neighbour ENN with mode voting to majority observations only. It removes majority observations whose local vote disagrees, while retaining all original and generated minority observations. It therefore does not remove minority label noise. CASB-ROS returns to the original 50, 30 and 20 quotas and duplicates selected sources rather than interpolating. Unlike ordinary ROS, replication is guided by the overlapping CASB pools.',
 headers=['Extension','Change from original CASB','Meaning'],rows=[['Relaxed','70 / 20 / 10; remove step caps','Allow wider interpolation'],['Edited','Relaxed, then majority-only 3-NN ENN','Remove locally disagreeing majority points'],['ROS','50 / 30 / 20; copy chosen sources','Test pool-guided repetition']],widths=[.18,.43,.39],take='All three reuse CASB source pools; each changes allocation, generation or cleaning.')
add('table','Four CASB variants','04  Proposed method',
 'Coverage, border and rare are the three quota columns. The original and replication variants use 50, 30 and 20 percent. Relaxed and edited use 70, 20 and 10 percent. Edited first generates using the relaxed rule and then removes original-majority observations that disagree with a three-neighbour mode vote. Original versus relaxed changes both the quotas and interpolation limits, so it is not a clean cap-only ablation.',
 headers=['Variant','C / B / R quota','Generation','Cleaning'],rows=[['CASB','50 / 30 / 20','Conditional cap','None'],['CASB-relaxed','70 / 20 / 10','Full segment','None'],['CASB-edited','70 / 20 / 10','Full segment','Majority-only ENN'],['CASB-ROS','50 / 30 / 20','Exact duplication','None']],widths=[.25,.23,.26,.26],take='Quotas allocate generated samples, not disjoint fractions of the original data.')
plot('What resampling changes','04  Proposed method','paper_material/14_final_distribution_panels.png','Same constructed input, seed and ratio. Grey crosses mark removed majority points.',
 'Compare every output with the original input. SMOTE and the interpolating CASB variants add coordinates; CASB-ROS repeats coordinates, shown using multiplicity rings. The edited variant also removes majority observations. These panels explain the mechanism using a constructed example. They do not measure classification performance and are not a real KEEL dataset.')
plot('Generation can be audited','04  Proposed method','paper_material/13_audited_generation_walkthrough.png','Source, neighbour, branch and interpolation step can be traced for each new point.',
 'This example contains 240 majority and 40 minority observations, with seed 42 and a target ratio of 0.75. Bubble area shows source selection mass. Green markers show generated observations. The red ring identifies an error injected when the example was constructed; CASB did not discover it. The audit is useful for checking the actual generation rule, but it is not evidence of reliable noise detection.')
plot('A real-data view: Abalone19','04  Proposed method','paper plot/abalone19_PCA_comparison.png','Original training data and resampled views share the same PCA axes.',
 'This is the Abalone19 case study used in our paper. Start with the original training distribution, then compare SMOTE and Borderline-SMOTE with the four CASB variants. Grey and blue show original majority and minority observations; orange triangles mark generated samples, and green rings identify added duplicates. The projection is fitted on original training data, while resampling takes place in the full encoded feature space. The Sex feature is one-hot encoded, so interpolation may produce fractional dummy values. This visual comparison shows how generation changes the training distribution; it does not prove that synthetic labels are correct or establish performance by itself.')
add('table','Average scores across the benchmark','05  Results and comparison',
 'These percentages give each of the 40 complete datasets and each of the four classifiers equal weight. Each row is a fixed method, not a different selected winner on each dataset. CASB-edited has the largest mean G-mean and recall among these methods. CASB has the largest mean F1 and precision among the eight resamplers in this table. These descriptive averages do not establish statistical significance. No-resampling remains available in the full evidence archive.',
 source='statistical result/average_metric_scores.csv: strict_all_methods, SVM/KNN/RF/LR',headers=['Method','G-mean','F1','Precision','Recall'],rows=avg,widths=[.32,.17,.17,.17,.17],take='40 matched datasets × 4 classifiers; equal weights; scores in percent',small=True)
# Reproduce Table 6 directly, preserving printed values and winner formatting.
import re
paper=(ROOT/'latex_paper/manuscript.tex').read_text(encoding='utf-8')
block=paper.split('BEGIN TABLE: tables/benchmark_comparison',1)[1].split('END TABLE: tables/benchmark_comparison',1)[0]
groups={}; metric=None
for line in block.splitlines():
    if ' & ' not in line or not re.search(r'0\.\d{3}',line): continue
    cells=line.split('&')
    if cells[0].strip(): metric=cells[0].strip()
    vals=[]; bold=[]
    for j,cell in enumerate(cells[2:]):
        value=re.search(r'0\.\d{3}',cell)
        assert value
        vals.append(value.group())
        if '\\textbf' in cell: bold.append(j+1)
    groups.setdefault(metric,[]).append(([cells[1].strip()]+vals,bold))
assert len(groups)==4 and all(len(v)==6 for v in groups.values())
for metric,entries in groups.items():
    add('table',f'Table 6 | {metric} by classifier','05  Results and comparison',
        f'This reproduces the {metric} panel of Table 6 from the paper. Rows show SVM, KNN, random forest, logistic regression, the equal SVM/KNN average and the equal four-classifier average. Every method uses the same 40 complete matched tasks. Values are fractions, exactly as printed in the paper. Bold coloured cells preserve the winners identified using unrounded scores, so equally rounded values may not both be highlighted. NORES means no resampling. A high score on one metric should be interpreted alongside the other metrics, and these averages alone do not establish statistical significance.',
        source='latex_paper/manuscript.tex: Table 6, benchmark_comparison',
        headers=['Classifier','NORES','ROS','SMOTE','B-SMOTE','ADASYN','CASB','CASB\nrelaxed','CASB\nedited','CASB\nROS'],
        rows=[e[0] for e in entries],bold_cells=[[i+2,j+1] for i,e in enumerate(entries) for j in e[1]],
        widths=[.14]+[.86/9]*9,small=True,
        take='40 matched datasets | Scores: 0 to 1 | Highlighted cells: row winners | NORES: no resampling')
plot('Performance varies by metric','05  Results and comparison','paper_material/06_average_score_differences.png','Positive differences favour the named CASB variant; negative values remain visible.',
 'This plot compares collection-wide score differences between fixed variants and baselines. Read one metric at a time. The edited variant tends to improve recall and G-mean while paying a precision cost. Other variants can preserve precision better. The differences depend on the classifier and metric, so the plot does not justify describing the entire family as universally superior.')
add('table','Best family averages by classifier','05  Results and comparison',
 'For each classifier and metric, this table compares the highest collection-wide CASB-variant mean with the strongest mean of the four core baselines. This selection is retrospective and can choose a different variant for each metric. SVM, KNN and LR lead descriptively on all four metrics. RF leads on three, but its best family F1 is 0.052 percentage points below SMOTE. SVM G-mean differs by only 0.019 points, so it should not be described as a large improvement.',
 source='latex_paper/tables/envelope.tex',headers=['Classifier','G-mean gain','F1 gain','Precision gain','Recall gain'],rows=[['SVM','+0.019','+0.494','+1.935','+1.603'],['KNN','+0.204','+0.670','+0.911','+0.617'],['RF','+2.031','−0.052','+0.881','+3.930'],['LR','+0.145','+0.363','+0.888','+1.253']],widths=[.2,.2,.2,.2,.2],take='Percentage-point differences vs strongest core baseline; retrospective per-metric selection')
plot('G-mean under controlled overlap','05  Results and comparison','paper_material/17_overlap_gmean.png','Smaller class-centre distance means greater overlap. Each curve shows a fixed method.',
 'This is a separate two-dimensional Gaussian simulation, not an average of the KEEL datasets. It uses a 10-to-1 class ratio, 20 independent seeds and four classifiers. Distance changes overlap while preserving the underlying draws within a seed. Bands are pointwise confidence intervals. Incomplete settings are withheld. The curves help explain behaviour under overlap, but they do not test resistance to corrupted labels.')
plot('A real-data view: Haberman','05  Results and comparison','paper plot/haberman_PCA_comparison.png','PCA is fitted on the original training data; generation occurs in the full feature space.',
 'Haberman is a retrospectively chosen positive case study. The panels share the same PCA projection. Green additions and replication rings show how the samplers change training observations. Method-specific ratios come from saved SVM validation, so sample counts can differ. Similar-looking SMOTE and CASB clouds are expected because both use interpolation. A two-dimensional projection cannot certify label correctness or explain every performance difference.')
add('table','Family wins against all four core baselines','06  Win counts and statistical tests',
 'A win means at least one CASB-family variant exceeds the strongest of SMOTE, Borderline-SMOTE, ROS and ADASYN on that dataset and metric. The denominator is the same 40 matched datasets. The family includes CASB, relaxed, edited and CASB-ROS. RF has 28 G-mean wins and 26 F1 wins, but those can involve different variants. Joint wins require the same variant to beat all four baselines on both G-mean and F1. These are descriptive, retrospective counts, not corrected significance tests.',
 source='latex_paper/tables/family.tex: Core four',headers=['Classifier','G-mean','F1','Precision','Recall','Joint*'],rows=[['SVM','15','19','20','17','10'],['KNN','20','19','21','17','12'],['RF','28','26','21','26','20'],['LR','15','17','19','16','9']],widths=[.2,.16,.16,.16,.16,.16],take='Out of 40 datasets. *Same variant wins both G-mean and F1. Per-metric family selection is retrospective.')
add('flow','What a family win means','06  Win counts and statistical tests',
 'Imagine we take one dataset and one metric. We find the best score among the four CASB variants, then compare it with the best score among the four baselines. If the family score is strictly larger, that is one family win. Repeating this after observing test results is an optimistic family envelope. It is not a deployable method-selection procedure. A practical selector must choose the variant using training-only validation before seeing the test result.',
 steps=['One dataset + metric','Best CASB variant','Strongest baseline','Strictly higher?'],details=['40 matched tasks','May vary by task','SMOTE / B-SMOTE / ROS / ADASYN','Count one family win'],take='A fixed method and a test-selected family envelope answer different questions.')
add('flow','Statistical testing protocol','06  Win counts and statistical tests',
 'The independent comparison unit is a dataset-level mean, not each fold or seed. Friedman asks whether methods differ somewhere across a matched cohort. Paired two-sided Wilcoxon tests compare each fixed variant with a baseline. Holm adjusts for multiple comparisons within each classifier. Finally, source-family sensitivity analyses reduce the influence of related dataset variants. We report the tests that do not reject as well as the significant gains and losses.',
 steps=['Dataset means','Friedman','Wilcoxon + Holm','Sensitivity checks'],details=['Average folds and seeds','Any method differences?','Fixed variant vs baseline','Group related tasks'],take='A significant omnibus test does not prove that CASB is the winner.')
add('table','Corrected fixed-variant comparisons','06  Win counts and statistical tests',
 'The table counts corrected comparisons across four metrics for each classifier. SVM and KNN have 112 tests each because compatible legacy controls are available. RF and LR have 80 each. Higher means a significant benefit for a fixed CASB variant, lower means a significant loss, and the remaining results are not significant. All 16 matched Friedman metric/classifier tests reject, but that only establishes that some methods differ.',
 source='latex_paper/tables/significance.tex and friedman.tex',headers=['Classifier','Tests','CASB higher','CASB lower','Not significant'],rows=[['SVM','112','27','4','81'],['KNN','112','18','13','81'],['RF','80','21','4','55'],['LR','80','14','5','61']],widths=[.2,.14,.22,.22,.22],take='All 16 Friedman tests reject; pairwise gains and losses still depend on variant and metric.')
add('contrast','Related datasets weaken the evidence','06  Win counts and statistical tests',
 'Several benchmark tasks come from the same original source dataset. Treating all variants as fully independent may overstate the amount of evidence. We therefore aggregate paired differences within named source families and also examine one representative task per family. No fixed-variant Wilcoxon comparison survives Holm correction under either sensitivity view. The grouped exact sign test has nine corrected rejections, so the conclusion depends on the test and unit. This motivates validation on genuinely new source families.',
 values=['0','9'],labels=['Corrected Wilcoxon rejections\nin either source-family view','Corrected sign-test rejections\nin the family-mean view'],take='Dataset-level significance does not establish independent-family superiority.')
add('table','Limitations and next experiments','07  Conclusion and future work',
 'The variants change more than one design choice, so we need matched ablations of quotas, caps and cleaning. The most immediate cleaner control is SMOTE followed by exactly the same majority-only ENN procedure. The existing overlap experiment does not test corrupted training labels. For categorical inputs, fractional one-hot values motivate a categorical-aware generator. Finally, the protocol and classifier set should be frozen before testing new source families, including comparisons with close methods such as LNE and UGO.',
 headers=['Current limitation','Next experiment'],rows=[['Quota and cap effects are mixed','Vary one component at a time'],['Cleaner contributes to edited results','Match SMOTE with the same ENN settings'],['Noise and categorical handling remain open','Clean-test label-noise and categorical-aware studies'],['Related tasks and development reuse','Frozen evaluation on new source families']],widths=[.5,.5],take='Future work should test the explanation, not only seek a higher score.')
add('bullets','Conclusion','07 Conclusion and future work',
 'CASB provides an auditable way to distribute generation across overlapping minority source pools. The four variants expose useful tradeoffs, especially the recall and precision effects of majority editing. RF shows the strongest family G-mean win count in this matched comparison. The corrected tests support selected fixed-variant gains but also reveal losses and weaker evidence under source-family grouping. The defensible contribution is a reproducible design and measured tradeoffs, not universal superiority.',
 bullets=['CASB makes source allocation explicit and auditable','Editing often improves recall while reducing precision','RF: family G-mean wins on 28 of 40 matched tasks','Independent-family validation remains essential'],take='Contribution: a reproducible framework with measured, classifier-dependent tradeoffs.')
add('closing','Thank you','Questions',
 'Thank you. I welcome questions about source selection, the difference between a family win and a fixed-variant win, the evaluation protocol, and the next experiments. If asked whether the method always beats SMOTE, the answer is no. The results depend on the metric, classifier and dataset. If asked about novelty, describe the particular implemented combination and acknowledge close prior work.',
 subtitle='Questions and discussion',take='Pulkit Sharma  •  Priyanshu Kumar  •  Niranjan Yadav\nDepartment of Artificial Intelligence, SVNIT Surat')
# Requested objective revision and removal of the former slide 35.
slides[:] = [slide for slide in slides if slide['title'] != 'Related datasets weaken the evidence']
for slide in slides:
    if slide['title'] == 'Research objectives':
        slide['bullets'] = ['Reduce confusion near minority-majority class boundaries', 'Address intra-class imbalance across dense and sparse minority regions', 'Compare CASB variants and their precision-recall tradeoffs', 'Evaluate performance across datasets and classifiers']
        slide['notes'] = 'Our first aim is to reduce confusion near the boundary between the minority and majority classes. CASB uses local labels to identify mixed regions and limits interpolation in selected branches. Our second aim is to address intra-class imbalance: some minority regions contain many observations while others are sparsely represented. The coverage and rare pools provide source eligibility and a generation budget for these regions. These are design objectives, not established guarantees that all boundary ambiguity or intra-class imbalance is removed. We compare the variants and examine precision, recall, F1 and G-mean across datasets and classifiers.'
        slide['take'] = 'Aim: support difficult boundary regions and sparsely represented minority regions.'
# Four priority limitations, paired with concrete future work.
for slide in slides:
    if slide['title'] == 'Limitations and next experiments':
        slide['rows'] = [
            ['Synthetic labels are not guaranteed correct', 'Validate generated samples with stronger local checks'],
            ['Coverage can repeat minority noise; editing retains it', 'Test minority-noise detection and robust source selection'],
            ['Straight lines may cross curved or disconnected regions', 'Study geometry-aware generation'],
            ['Related datasets; classifier- and metric-dependent gains', 'Validate on independent sources with a frozen protocol']
        ]
        slide['notes'] = 'Four limitations are especially important. First, a distance cap restricts movement but does not prove that a generated point has the correct class label. Second, the coverage pool includes every minority observation, including potentially noisy labels; majority-only editing cannot remove mislabeled minority observations. Third, straight-line interpolation may be unsuitable when minority regions are curved or disconnected. Fourth, several benchmark tasks share source datasets, and performance varies by classifier and metric, so the evidence does not establish universal or independent-family superiority. Future work should evaluate stronger validation checks, robust source selection, geometry-aware generation and a frozen protocol on new independent sources.'
# Brief explanations fill sparse slides without adding paragraphs.
for slide in slides:
    if slide['kind'] == 'problem':
        slide['bullets'] = ['100 observations: 95 majority and only 5 minority', 'Predict majority for every case: 95 correct, but all 5 minority cases missed', 'Goal: detect minority cases while controlling false positives']
    elif slide['kind'] == 'contrast':
        slide['bullets'] = ['Related task variants do not provide fully independent evidence', 'Grouping by source family makes the conclusion more cautious', 'Next step: freeze the method and test on new source families']
    insights = {
        'Established resampling methods': 'CASB asks: can broad source eligibility coexist with targeted generation?',
        'Closest ideas in previous work': 'The contribution lies in the implemented combination, not in discovering minority types.',
        'Four metrics describe different costs': 'High recall alone is insufficient: check precision and F1 alongside G-mean.',
        'Step 1: identify useful minority sources': 'Pools overlap: one minority observation can belong to coverage, border and rare.',
        'Step 3: limit movement using majority distance': 'Example: neighbour distance = 4, majority distance = 2; ordinary capped movement <= 1.',
        'The three extensions: what changes?': 'Edited preserves minority points; ROS repeats coordinates rather than creating new ones.',
        'Corrected fixed-variant comparisons': 'Count significant gains and losses separately; non-significance is not proof of equality.',
        'Limitations and next experiments': 'Priority: matched ablations, stronger comparison methods and independent validation.'
    }
    if slide['title'] in insights:
        slide['insight'] = insights[slide['title']]
# Plain-language speaking script, separate from short on-slide text.
easy_notes=json.loads((OUT/'easy_notes.json').read_text(encoding='utf-8'))
assert len(easy_notes)==len(slides)
for slide,note in zip(slides,easy_notes):
    if note=='PLACEHOLDER':
        metric=slide['title'].split('| ')[1].split(' by')[0]
        meaning={'G-mean':'how well both classes are detected','F1':'the balance between minority precision and recall','Precision':'how often a minority prediction is correct','Recall':'how many real minority cases we find'}[metric]
        note=f'This is the {metric} part of Table 6 from our paper. It measures {meaning}. Read one classifier row at a time and compare the methods across that row. Scores here run from zero to one, so 0.8 means 80 percent. The coloured bold cell is the winner based on the full unrounded score. Two displayed values can look equal because we round them. NORES means no resampling. The last rows average classifiers equally. All methods use the same 40 complete datasets. These averages do not by themselves prove a statistically significant difference.'
    slide['notes']=note
from formula_slides import revise
revise(slides)
OUT.mkdir(parents=True,exist_ok=True)
(OUT/'slides.json').write_text(json.dumps(slides,ensure_ascii=False,indent=2),encoding='utf-8')
guide=['# CASB research presentation: presenter guide','', 'Use PowerPoint Presenter View to read these notes while the audience sees the slide. Suggested duration: 20–25 minutes, with extra time for questions.','']
for i,s in enumerate(slides,1):guide.extend([f'## Slide {i}: {s["title"]}','',s['notes'],'',f'Source: `{s["source"]}`',''])
(ROOT/'presentation/Presenter_Guide.md').write_text('\n'.join(guide),encoding='utf-8')
print(len(slides),'slides prepared; evidence table:',avg)
